Use ASP.NET Core's **`WebApplicationFactory<T>`** — it hosts your app in-process with a test HTTP client, no real port needed.

### Setup

```bash
dotnet add package Microsoft.AspNetCore.Mvc.Testing
dotnet add package xunit
```

### Example test

```csharp
public class McpIntegrationTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpIntegrationTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsServerCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test-client", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2.0", body.GetProperty("jsonrpc").GetString());
        Assert.Equal(1, body.GetProperty("id").GetInt32());
        Assert.True(body.GetProperty("result").TryGetProperty("capabilities", out _));
    }

    [Fact]
    public async Task ToolsList_ReturnsRegisteredTools()
    {
        // Initialize first (stateful servers may require it)
        await InitializeAsync();

        var request = new { jsonrpc = "2.0", id = 2, method = "tools/list" };
        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        var tools = body.GetProperty("result").GetProperty("tools");
        Assert.True(tools.GetArrayLength() > 0);
    }

    private async Task InitializeAsync()
    {
        var init = new
        {
            jsonrpc = "2.0", id = 0, method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test", version = "1.0" }
            }
        };
        await _client.PostAsJsonAsync("/mcp", init);
    }
}
```

### Key points

- **`WebApplicationFactory<Program>`** boots your real `Program` pipeline (middleware, DI, routing) but uses an in-memory test server — no ports, no network.
- Override services for testing via `factory.WithWebHostBuilder(b => b.ConfigureServices(...))` to swap in mocks (e.g., fake DB, stub external APIs).
- If your server uses **SSE transport**, the same approach works — read the SSE stream with `HttpCompletionOption.ResponseHeadersRead` and parse `text/event-stream` lines incrementally.
- Make sure `Program` is visible to your test project (add `InternalsVisibleTo` or a `public partial class Program { }` marker).
